  '44': {
    title: 'Repeal',
    description:
      'Directive (EU) 2016/1148 is repealed with effect from 18 October 2024.\nReferences to the repealed Directive shall be construed as references to this Directive and shall be read in accordance with the correlation table set out in Annex III.',
    category: 'CHAPTER IX - FINAL PROVISIONS',
  },
